    'cvpartition', 'stats', 'all'; 'crossval', 'stats', 'all'; 'rng', 'matlab/ref', 'all'; 'randperm', 'matlab/ref', 'all';
    'spline', 'matlab/ref', 'all'; 'ppval', 'matlab/ref', 'all'; 'polyfit', 'matlab/ref', 'all'; 'polyval', 'matlab/ref', 'all';
    'fill', 'matlab/ref', 'all'; 'cordexch', 'stats', 'all'; 'fracfact', 'stats', 'all'; 'daugment', 'stats', 'pro';
    'lillietest', 'stats', 'pro'; 'skewness', 'stats', 'pro'; 'kurtosis', 'stats', 'pro'; 'norminv', 'stats', 'pro';
    'histogram', 'matlab/ref', 'pro'; 'corr', 'stats', 'pro'; 'anovan', 'stats', 'pro'; 'boxchart', 'matlab/ref', 'pro';
